    if d > _년후(전환, 2):
        return {"조특_38의2_전환지주회사요건": {"충족": False, "사유": "전환일부터 2년 경과(2호)"}}
    if ctx.사실값("자기주식교환") and not (ctx.사실값("모든주주참여") and ctx.값("조특_영35의3_공시요건", False)):
        return {"조특_38의2_전환지주회사요건": {"충족": False, "사유": "모든 주주 참여·공시 요건 미충족(3호)"}}
