@법("38의2", "3", 제목="지주회사 특례 방법 — 내국법인: 양도 사업연도와 3개 사업연도 불산입 후 3년 균분 익금산입, 거주자: 확정신고기한 종료일 후 3년이 되는 날부터 3년간 균분 납부",
    원문="③ 1. 내국법인: 양도차익 상당액을 양도일이 속하는 사업연도와 그 종료일 이후 3개 사업연도의 기간 중 익금에 산입하지 아니하고 그 다음 3개 사업연도의 기간 동안 균분한 금액 이상을 익금에 산입 2. 거주자: 양도소득세를 양도일이 속하는 연도의 과세표준 확정신고기한 종료일 이후 3년이 되는 날부터 3년의 기간 동안 균분한 금액 이상을 납부",
    산출=("조특_38의2_이연방법",), 비고="거주자 확정신고기한(소득세법)은 사실 '확정신고기한'으로 호출자가 넘김")
def 법38의2_3(ctx):
    유형 = ctx.사실값("주주유형")
    if 유형 == "법인":
        a, d = ctx.사실값("양도차익"), _d(ctx.사실값("현물출자일"))
        if a is None or d is None:
            return 미적용("양도차익·현물출자일 미제출")
        return {"조특_38의2_이연방법": _이연스케줄(a, d.year, 3)}
    if 유형 == "거주자":
        세, 기한 = ctx.사실값("양도소득세"), _d(ctx.사실값("확정신고기한"))
        if 세 is None or 기한 is None:
            return 미적용("양도소득세·확정신고기한 미제출")
        시작 = _년후(기한, 3)
        return {"조특_38의2_이연방법": {"분할납부개시일": _iso(시작), "분할납부": _균분(세, 시작.year)}}
    return 미적용("주주유형(법인|거주자) 미제출")


