@법("44", "1", 제목="재무구조개선 채무면제익 — 2026.12.31까지 회생계획·기업개선약정·채권자 합의·적기시정 등으로 금융채권자에게 면제받은 채무(결손금 초과분)를 4개 사업연도 불산입 후 3년 균분",
    원문="① 2026년 12월 31일까지 내국법인이 금융채권자로부터 채무의 일부를 면제받은 경우로서 1. 회생계획인가 결정에 면제액 포함 2. 기업구조조정 촉진법 기업개선계획 약정(반대채권자 채권매수청구 관련 포함) 3. 금융채권자 간의 합의 4. 관계 법률에 따라 면제받은 경우로서 대통령령으로 정하는 경우 채무면제익은 해당 사업연도와 종료일 이후 3개 사업연도 익금불산입, 그 다음 3개 사업연도 균분 익금산입",
    산출=("조특_44_채무면제익", "조특_44_익금산입스케줄"), 종료일="20261231")
def 법44_1(ctx):
    d = _d(ctx.사실값("면제일"))
    if d is None:
        return 미적용("채무면제일 미제출")
    if d > date(2026, 12, 31):
        return 미적용("2026년 12월 31일 후 면제")
    if ctx.사실값("면제사유") not in _면제사유:
        return 미적용("§44① 각 호 면제 사유 아님")
    a = ctx.값("조특_영41_채무면제익", None)
    if a is None:
        return 미적용("채무면제익 계산 사실 미제출")
    return {"조특_44_채무면제익": a, "조특_44_익금산입스케줄": _이연스케줄(a, d.year, 3)}


