@법("45", "1", 제목="감자 과세특례 — 2012.12.31 이전 계획에 따라 주주로부터 무상으로 받아 소각한 주식가액(결손금 초과분) 익금불산입",
    원문="① 내국법인이 2012년 12월 31일 이전에 재무구조개선계획에 따라 주주등으로부터 해당 법인의 주식등을 무상으로 받아 소각하는 경우 해당 주식등의 가액(결손금 초과분)은 익금에 산입하지 아니한다",
    산출=("조특_45_익금불산입액",), 종료일="20121231")
def 법45_1(ctx):
    d = _d(ctx.사실값("주식수증일"))
    if d is None:
        return 미적용("주식 수증일 미제출")
    if d > date(2012, 12, 31):
        return 미적용("2012년 12월 31일 후(일몰)")
