@법("46의4", "2", 제목="자가물류시설 사후 — 3년 내 폐업·해산 또는 영 기간 각 사업연도 제3자물류비용 비율 70% 미만·제3자물류비용 < 양도차익 × 법인세율 × 이자율이면 미산입 전액 익금산입(이자는 제33조제3항 후단 준용)",
    원문="② 양도일 이후 3년 이내에 폐업하거나 해산한 경우 또는 1. 양도 후 대통령령으로 정하는 기간 동안 각 사업연도에 지출한 물류비용 중 특수관계인 외의 자에게 지출한 물류비용(제3자물류비용)이 100분의 70 이상 2. 각 사업연도의 제3자물류비용이 양도차익에 가. 법인세법 제55조에 따른 세율 나. 대통령령으로 정하는 이자율을 곱하여 계산한 금액 이상 요건을 충족하지 못한 경우 익금에 산입. 제33조제3항 후단 준용",
    산출=("조특_46의4_사후익금산입액",), 비고="법인세율(법인세법 제55조)·이자율(재정경제부령)은 사실 '법인세율'·'물류이자율'로 호출자가 넘김")
def 법46의4_2(ctx):
    잔 = ctx.사실값("미산입잔액")
    if 잔 is None:
        return 미적용("미산입 잔액 미제출")
    양도, 폐업 = _d(ctx.사실값("양도일")), _d(ctx.사실값("폐업해산일"))
    if 양도 and 폐업 and 폐업 <= _년후(양도, 3):
        return {"조특_46의4_사후익금산입액": int(잔)}
    연도별 = ctx.사실값("연도별_물류비용") or {}
    차, 세, 이 = ctx.사실값("양도차익"), ctx.사실값("법인세율"), ctx.사실값("물류이자율")
    기간 = ctx.값("조특_영43의4_사후관리연도", [])
    for y in 기간:
        v = 연도별.get(y)
        if v is None:
            continue
        총, 제3 = v
        if 총 and float(제3) / float(총) < 0.7:
            return {"조특_46의4_사후익금산입액": int(잔)}
        if 차 is not None and 세 is not None and 이 is not None and float(제3) < float(차) * float(세) * float(이):
            return {"조특_46의4_사후익금산입액": int(잔)}
    return {"조특_46의4_사후익금산입액": 0}


