@법("47의3", "", 제목="벤처기업 합병 이월결손금 승계 — 2012.12.31까지, 법인세법 제44조②요건(R&D 자산취득·지출 후 1년 지나면 1년 사업 간주) 시 승계결손금 범위 공제",
    원문="법인이 2012년 12월 31일까지 벤처기업을 합병하는 경우로서 법인세법 제44조제2항 각 호의 요건(벤처기업이 연구ㆍ개발 등을 위하여 자산을 취득하거나 비용을 지출한 때부터 1년이 지난 경우 1년 이상 계속 사업 간주)을 갖춘 경우 피합병법인의 결손금은 대통령령으로 정하는 금액의 범위에서 공제",
    산출=("조특_47의3_공제가능결손금",), 종료일="20121231")
def 법47의3(ctx):
    d = _d(ctx.사실값("합병일"))
    if d is None:
        return 미적용("합병일 미제출")
    if d > date(2012, 12, 31):
        return 미적용("2012년 12월 31일 후(일몰)")
    사업 = float(_f(ctx, "사업기간_년", 0)) >= 1 or float(_f(ctx, "연구개발지출후_년", 0)) >= 1
    if not (사업 and ctx.사실값("법인세법44조2항_기타요건")):
        return 미적용("법인세법 제44조제2항 요건 미충족")
    v = ctx.값("조특_영44의3_승계결손금", None)
    if v is None:
        return 미적용("승계결손금 미제출")
    return {"조특_47의3_공제가능결손금": v}


